  "开启后，模型名称会参与 cache key（不同模型隔离）。": "開啓後，模型名稱會參與 cache key（不同模型隔離）。",
  "开启后，视频生成页面仅会展示此模型，不再依赖模型名称关键字判断": "開啟後，影片生成頁面僅會展示此模型，不再依賴模型名稱關鍵字判斷",
  "开启后，若该规则命中且请求失败，将不会切换渠道重试。": "開啓後，若該規則命中且請求失敗，將不會切換渠道重試。",
  "开启后，规则名称会参与 cache key（不同规则隔离）。": "開啓後，規則名稱會參與 cache key（不同規則隔離）。",
