  "此操作将禁用该用户当前的两步验证配置，下次登录将不再强制输入验证码，直到用户重新启用。": "此操作將禁用該使用者當前的兩步驗證設定，下次登錄將不再強制輸入驗證碼，直到使用者重新啟用。",
