  "此设置用于系统内部计算，默认值500000是为了精确到6位小数点设计，不推荐修改。": "此設定用於系統內部計算，預設值500000是為了精確到6位小數點設計，不推薦修改。",
  "此页面仅显示未设置价格或倍率的模型，设置后将自动从列表中移除": "此頁面僅顯示未設定價格或倍率的模型，設定後將自動從列表中移除",
  "此页面仅显示未设置价格或基础倍率的模型，设置后会自动从列表中移出": "此頁面僅顯示未設定價格或基礎倍率的模型，設定後會自動從列表中移出",
  "此项只读，需要用户通过个人设置页面的相关绑定按钮进行绑定，不可直接修改": "此項唯讀，需要使用者透過個人設定頁面的相關綁定按鈕進行綁定，不可直接修改",
  "此项可选，用于修改请求体中的模型名称，为一个 JSON 字符串，键为请求中模型名称，值为要替换的模型名称，例如：": "此項可選，用於修改請求體中的模型名稱，為一個 JSON 字符串，鍵為請求中模型名稱，值為要替換的模型名稱，例如：",
  "此项可选，用于修改请求体中的模型名称，为一个 JSON 字符串，键为请求中模型名称，值为要替换的模型名称，留空则不更改": "此項可選，用於修改請求體中的模型名稱，為一個 JSON 字符串，鍵為請求中模型名稱，值為要替換的模型名稱，留空則不更改",
  "此项可选，用于复写返回的状态码，仅影响本地判断，不修改返回到上游的状态码，比如将claude渠道的400错误复写为500（用于重试），请勿滥用该功能，例如：": "此項可選，用於複寫返回的狀態碼，僅影響本地判斷，不修改返回到上游的狀態碼，比如將claude管道的400錯誤複寫為500（用於重試），請勿濫用該功能，例如：",
  "此项可选，用于覆盖请求参数。不支持覆盖 stream 参数": "此項可選，用於覆蓋請求參數。不支援覆蓋 stream 參數",
  "此项可选，用于覆盖请求头参数": "此項可選，用於覆蓋請求頭參數",
  "此项可选，用于通过自定义API地址来进行 API 调用，末尾不要带/v1和/": "此項可選，用於透過自訂API位址來進行 API 調用，末尾不要帶/v1和/",
  "每个充值单位对应的 USD 金额，默认 1.0": "每個充值單位對應的 USD 金額，默認 1.0",
  "每个分组代表一个价格档位。管理员创建分组后，可以选择哪些档位对用户开放自选。": "每個分組代表一個價格檔位。管理員建立分組後，可以選擇哪些檔位對使用者開放自選。",
  "每个对比项都可选择来源（本站/外部平台），再分别选择分组和模型进行可视化对比。各来源按自己的汇率计算。": "每個對比項都可選擇來源（本站/外部平臺），再分別選擇分組和模型進行可視化對比。各來源按自己的匯率計算。",
  "每个档位可设置 0~2 个条件（对 len、p 和 c），最后一档为兜底档无需条件。len 为输入上下文总长度（含缓存），推荐用于阶梯条件。": "每個檔位可設置 0~2 個條件（對 len、p 和 c），最後一檔爲兜底檔無需條件。len 爲輸入上下文總長度（含緩存），推薦用於階梯條件。",
