  '键为分组名称，值为另一个 JSON 对象，键为分组名称，值为该分组的用户的特殊分组倍率，例如：{"vip": {"default": 0.5, "test": 1}}，表示 vip 分组的用户在使用default分组的令牌时倍率为0.5，使用test分组时倍率为1': '鍵為分組名稱，值為另一個 JSON 對象，鍵為分組名稱，值為該分組的使用者的特殊分組倍率，例如：{"vip": {"default": 0.5, "test": 1}}，表示 vip 分組的使用者在使用default分組的令牌時倍率為0.5，使用test分組時倍率為1',
  "键为原状态码，值为要复写的状态码，仅影响本地判断": "鍵為原狀態碼，值為要複寫的狀態碼，僅影響本地判斷",
  '键为用户分组名称，值为操作映射对象。内层键以"+:"开头表示添加指定分组（键值为分组名称，值为描述），以"-:"开头表示移除指定分组（键值为分组名称），不带前缀的键直接添加该分组。例如：{"vip": {"+:premium": "高级分组", "special": "特殊分组", "-:default": "默认分组"}}，表示 vip 分组的用户可以使用 premium 和 special 分组，同时移除 default 分组的访问权限': '鍵為使用者分組名稱，值為操作映射對象。內層鍵以"+:"開頭表示添加指定分組（鍵值為分組名稱，值為描述），以"-:"開頭表示移除指定分組（鍵值為分組名稱），不帶前綴的鍵直接添加該分組。例如：{"vip": {"+:premium": "高級分組", "special": "特殊分組", "-:default": "預設分組"}}，表示 vip 分組的使用者可以使用 premium 和 special 分組，同時移除 default 分組的存取權限',
  "键为端点类型，值为路径和方法对象": "鍵為端點類型，值為路徑和方法對象",
